//
// Input-level Integrated Gradients / Gradient SHAP of MLPerf Tiny ResNet-8 on
// GeMMX, generated by data/resnet8_xai_sched.py. The same step table runs
// once per sample: interpolate, forward (spilling ReLU activations to L3),
// backward to the input (transposed / polyphase convs on GeMMX, ReLU masks on
// both cores with activation chunks fetched from L3, DMA interleaves) and the
// attribution multiply-accumulate. Sample 0 is x itself: its forward pass is
// the inference and fixes the explained class. The final attribution is
// compared byte for byte with the emulator.

#include <stdint.h>

#include "snrt.h"             // write_csr, used by the generated cfg_* in data.h
#include "snax-gemmx-lib.h"
#include "data.h"

enum { OP_SAMPLE_IN = 1, OP_FILL, OP_GPOOL, OP_SPILL, OP_MASK, OP_DMAS, OP_ATTR };
#define N_PHASES 4

// g[i] = 0 where act == -128 (inactive ReLU); n multiple of 8, 2 words / iter.
static void relu_mask(int8_t *g, const int8_t *a, uint32_t n) {
    uint32_t *gw = (uint32_t *)g;
    const uint32_t *aw = (const uint32_t *)a;
    for (uint32_t i = 0; i < n / 4; i += 2) {
        uint32_t v0 = aw[i] ^ 0x80808080u, v1 = aw[i + 1] ^ 0x80808080u;
        uint32_t t0 = (((v0 & 0x7F7F7F7Fu) + 0x7F7F7F7Fu) | v0) & 0x80808080u;
        uint32_t t1 = (((v1 & 0x7F7F7F7Fu) + 0x7F7F7F7Fu) | v1) & 0x80808080u;
        gw[i] &= (t0 << 1) - (t0 >> 7);
        gw[i + 1] &= (t1 << 1) - (t1 >> 7);
    }
}

// Attribution MAC over rows [y0, y1): acc += (x - b) * g, 3 channels.
// Padded layout: pixel (y, x) at (y + 1) * 48 * 8 + (x + 8) * 8.
static void attr_mac(const int8_t *g, const int8_t *xv, const int8_t *bv, int32_t *acc,
                     int y0, int y1) {
    for (int y = y0; y < y1; y++)
        for (int x = 0; x < 32; x++) {
            int o = (y + 1) * 48 * 8 + (x + 8) * 8;
            int32_t *a = acc + (y * 32 + x) * 3;
            for (int c = 0; c < 3; c++) a[c] += ((int32_t)xv[o + c] - bv[o + c]) * g[o + c];
        }
}

static int argmax_logits(const int8_t *lg) {
    int pred = 0;
    for (int i = 1; i < 10; i++)
        if (lg[(i / 8) * 64 + (i % 8)] > lg[(pred / 8) * 64 + (pred % 8)]) pred = i;
    return pred;
}

int main() {
    uint8_t *l1 = (uint8_t *)snrt_l1_next();
    const int core0 = snrt_global_core_idx() == 0;
    const int dm = snrt_is_dm_core();
    if (dm) {
        snrt_dma_start_1d(l1, prog_image, PROG_IMAGE_BYTES);
        snrt_dma_start_1d(l1 + prog_blob_dst[PROG_FIRST_BLOB],
                          prog_params + prog_blob_off[PROG_FIRST_BLOB],
                          prog_blob_len[PROG_FIRST_BLOB]);
        snrt_dma_wait_all();
    }
    int32_t *attr = (int32_t *)(l1 + PROG_ATTR_OFF);
    for (int i = core0 ? 0 : 32 * 32 * 3; i < 32 * 32 * 3; i++) attr[i] = 0;
    snrt_cluster_hw_barrier();

    uint32_t phase_cyc[N_PHASES] = {0}, cfg = 0, run = 0, mask_c = 0, dma_c = 0, attr_c = 0;
    uint32_t sample_cyc[PROG_SAMPLES];
    int pred = -1;
    uint32_t t_start = snrt_mcycle();
    for (int smp = 0; smp < PROG_SAMPLES; smp++) {
        uint32_t ts = snrt_mcycle();
        for (int s = 0; s < PROG_N_STEPS; s++) {
            const xstep_t *st = &prog_steps[s];
            // ---- pre-ops
            for (int o = st->pre0; o < st->pre1; o++) {
                const op_t *op = &prog_ops[o];
                uint32_t a = snrt_mcycle();
                if (op->type == OP_SAMPLE_IN && dm) {
                    snrt_dma_start_1d(l1 + op->a, prog_l3 + PROG_L3_X, PROG_X_BYTES);
                    snrt_dma_start_1d(l1 + op->b, prog_l3 + prog_l3_b[smp], PROG_X_BYTES);
                    snrt_dma_start_1d(l1 + op->c, prog_l3 + prog_l3_bp[smp], 128);
                    snrt_dma_wait_all();
                } else if (op->type == OP_FILL && dm) {
                    snrt_dma_memset(l1 + op->a, (uint8_t)op->c, op->b);
                } else if (op->type == OP_GPOOL && core0 && smp == 0) {
                    pred = argmax_logits((const int8_t *)(l1 + op->a));
                    int8_t *gp = (int8_t *)(l1 + op->b);       // B blocks: ct, col, k=0
                    for (int c = 0; c < 64; c++) {
                        int8_t w = prog_fc_row(pred, c);
                        gp[(c / 8) * 64 + (c % 8) * 8] = w;
                    }
                }
                snrt_cluster_hw_barrier();
                if (core0) phase_cyc[st->phase] += snrt_mcycle() - a;
            }
            // ---- launch (+ prefetch of the next weight tile on the DMA core)
            if (dm && st->prefetch >= 0)
                snrt_dma_start_1d(l1 + prog_blob_dst[st->prefetch],
                                  prog_params + prog_blob_off[st->prefetch],
                                  prog_blob_len[st->prefetch]);
            if (core0 && st->launch >= 0) {
                uint32_t a = snrt_mcycle();
                cfg_fns[st->launch]((uint32_t)l1);
                uint32_t b = snrt_mcycle();
                set_gemmx_streamer_start();
                set_gemmx_start();
                wait_gemmx_and_streamer();
                uint32_t c = snrt_mcycle();
                cfg += b - a;
                run += c - b;
                phase_cyc[st->phase] += c - a;
            }
            if (dm) snrt_dma_wait_all();
            snrt_cluster_hw_barrier();
            // ---- post-ops
            for (int o = st->pre1; o < st->post1; o++) {
                const op_t *op = &prog_ops[o];
                uint32_t a = snrt_mcycle();
                if (op->type == OP_SPILL) {
                    if (dm) {
                        snrt_dma_start_1d(prog_l3 + op->b, l1 + op->a, op->c);
                        snrt_dma_wait_all();
                    }
                    snrt_cluster_hw_barrier();
                } else if (op->type == OP_MASK) {
                    // Interior rows only: fetch activation rows (2-D DMA from
                    // L3) in chunks, both cores mask half of the rows each.
                    const int ct = op->c >> 16, h = op->c & 0xFFFF;
                    const int w = op->d >> 16, wp = op->d & 0xFFFF;
                    const int plane = (h + 2) * wp * 8, row = w * 8;
                    const int rows = PROG_MCHUNK / row;
                    for (int c = 0; c < ct; c++)
                        for (int y0 = 0; y0 < h; y0 += rows) {
                            int nr = h - y0 < rows ? h - y0 : rows;
                            int base = c * plane + (y0 + 1) * wp * 8 + 64;
                            if (dm) {
                                snrt_dma_start_2d(l1 + PROG_MB, prog_l3 + op->b + base, row, row,
                                                  wp * 8, nr);
                                snrt_dma_wait_all();
                            }
                            snrt_cluster_hw_barrier();
                            int r0 = core0 ? 0 : nr / 2, r1 = core0 ? nr / 2 : nr;
                            if (core0 || dm)
                                for (int r = r0; r < r1; r++)
                                    relu_mask((int8_t *)(l1 + op->a + base + r * wp * 8),
                                              (const int8_t *)(l1 + PROG_MB + r * row), row);
                            snrt_cluster_hw_barrier();
                        }
                    if (core0) mask_c += snrt_mcycle() - a;
                } else if (op->type == OP_DMAS) {
                    if (dm) {
                        for (int d = op->a; d < op->b; d++) {
                            const dma2d_t *q = &prog_dmas[d];
                            snrt_dma_start_2d(l1 + q->dst, l1 + q->src, q->size, q->dst_stride,
                                              q->src_stride, q->repeat);
                        }
                        snrt_dma_wait_all();
                    }
                    snrt_cluster_hw_barrier();
                    if (core0) dma_c += snrt_mcycle() - a;
                } else if (op->type == OP_ATTR) {
                    if (dm) {
                        snrt_dma_start_1d(l1 + op->b, prog_l3 + PROG_L3_X, PROG_X_BYTES);
                        snrt_dma_start_1d(l1 + op->c, prog_l3 + prog_l3_b[smp], PROG_X_BYTES);
                        snrt_dma_wait_all();
                    }
                    snrt_cluster_hw_barrier();
                    const int8_t *g = (const int8_t *)(l1 + op->a);
                    const int8_t *xv = (const int8_t *)(l1 + op->b);
                    const int8_t *bv = (const int8_t *)(l1 + op->c);
                    if (core0) attr_mac(g, xv, bv, attr, 0, 16);
                    if (dm) attr_mac(g, xv, bv, attr, 16, 32);
                    snrt_cluster_hw_barrier();
                    if (core0) attr_c += snrt_mcycle() - a;
                }
                if (core0) phase_cyc[st->phase] += snrt_mcycle() - a;
            }
        }
        if (core0) sample_cyc[smp] = snrt_mcycle() - ts;
    }
    uint32_t t_end = snrt_mcycle();
    snrt_cluster_hw_barrier();

    uint32_t err = 0;
    if (core0) {
        printf("[TOTAL] %u cycles, %d samples x %d steps: config=%u run=%u mask=%u dma2d=%u "
               "attr=%u, explained class %d\n",
               t_end - t_start, PROG_SAMPLES, PROG_N_STEPS, cfg, run, mask_c, dma_c, attr_c, pred);
        for (int p = 0; p < N_PHASES; p++)
            printf("  %-9s %u\n", prog_phase_names[p], phase_cyc[p]);
        printf("  sample 0: %u  sample 1: %u cycles\n", sample_cyc[0],
               PROG_SAMPLES > 1 ? sample_cyc[1] : 0);
        for (int c = 0; c < PROG_N_CHECKS; c++) {
            const uint8_t *got = l1 + prog_check_off[c];
            const uint8_t *exp = prog_expected + prog_check_pos[c];
            uint32_t e = 0;
            for (int j = 0; j < prog_check_len[c]; j++) e += got[j] != exp[j];
            printf("check %-6s %s (%u/%d bytes differ)\n", prog_check_names[c],
                   e ? "FAIL" : "OK", e, prog_check_len[c]);
            err += e;
        }
    }
    snrt_cluster_hw_barrier();
    return err;
}
